export fn job_sequence_with_deadline(v:[*]const i64,n:usize)i64{if(n<1 or n>129)return -1;const count=v[0];if(count<0 or count>64 or n!=1+2*@as(usize,@intCast(count)))return -1;var d:[64]i64=@splat(0);var r:[64]i64=@splat(0);var order:[64]usize=@splat(0);for(0..@as(usize,@intCast(count)))|i|{d[i]=v[1+2*i];r[i]=v[2+2*i];if(d[i]< -1 or d[i]>64 or r[i]< -1000000 or r[i]>1000000)return -1;order[i]=i;}for(1..@as(usize,@intCast(count)))|i|{const key=order[i];var j=i;while(j>0 and r[order[j-1]]<r[key]){order[j]=order[j-1];j-=1;}order[j]=key;}var kept:i64=0;for(0..@as(usize,@intCast(count)))|i|{if(d[order[i]]>=@as(i64,@intCast(i+1)))kept+=1;}return kept;}
